#!/usr/bin/env bash
set -Eeuo pipefail

readonly SCRIPT_VERSION="2.30"
readonly ARCHIVE_SHA256="1baf07ba5aa9238d15e9f65d1f3e9093f025dcc0da5edb3243e88e1aa8dedf5d"
readonly INSTALL_DIR_NAME="mtproto-panel-v2.30"

for c in base64 tar gzip sha256sum mktemp awk; do
  command -v "$c" >/dev/null 2>&1 || { echo "Required command not found: $c" >&2; exit 1; }
done

if [[ ${EUID:-$(id -u)} -ne 0 && "${1:-}" != "--dry-run" && "${1:-}" != "--diagnostic" ]]; then
  echo "Run as root: sudo bash $0" >&2
  exit 1
fi

