PAYLOAD_B64

actual_sha="$(sha256sum "$PAYLOAD" | awk '{print $1}')"
if [[ "$actual_sha" != "$ARCHIVE_SHA256" ]]; then
  echo "Payload checksum mismatch: $actual_sha != $ARCHIVE_SHA256" >&2
  exit 1
fi

validate_tar_paths() {
  local archive="$1"
  tar -tzf "$archive" | awk '
    BEGIN { bad = 0 }
    /^\/+/{ print "Unsafe absolute tar path: " $0 > "/dev/stderr"; bad = 1 }
    /(^|\/)\.\.($|\/)/{ print "Unsafe parent traversal tar path: " $0 > "/dev/stderr"; bad = 1 }
    END { exit bad }
  '
}

validate_tar_paths "$PAYLOAD"
tar -xzf "$PAYLOAD" -C "$TMP_DIR" --no-same-owner --no-same-permissions
cd "$TMP_DIR/$INSTALL_DIR_NAME"
exec bash ./install.sh "$@"
